#include <stdio.h>
#include <stdint.h>

#define MAX_N 100000
#define MAX_Q 100000

// Segment tree with lazy propagation for range assignment and range sum
int64_t tree[4 * MAX_N];
int64_t lazy[4 * MAX_N];
int lazy_flag[4 * MAX_N]; // 1 if lazy value is set

void build(int node, int start, int end) {
    tree[node] = 0;
    lazy[node] = 0;
    lazy_flag[node] = 0;
    if (start != end) {
        int mid = (start + end) / 2;
        build(node * 2, start, mid);
        build(node * 2 + 1, mid + 1, end);
    }
}

void apply_lazy(int node, int start, int end) {
    if (lazy_flag[node]) {
        tree[node] = lazy[node] * (int64_t)(end - start + 1);
        if (start != end) {
            lazy[node * 2] = lazy[node];
            lazy[node * 2 + 1] = lazy[node];
            lazy_flag[node * 2] = 1;
            lazy_flag[node * 2 + 1] = 1;
        }
        lazy_flag[node] = 0;
    }
}

void range_assign(int node, int start, int end, int l, int r, int64_t val) {
    apply_lazy(node, start, end);
    if (start > r || end < l) return;
    if (l <= start && end <= r) {
        lazy[node] = val;
        lazy_flag[node] = 1;
        apply_lazy(node, start, end);
        return;
    }
    int mid = (start + end) / 2;
    range_assign(node * 2, start, mid, l, r, val);
    range_assign(node * 2 + 1, mid + 1, end, l, r, val);
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

int64_t range_sum(int node, int start, int end, int l, int r) {
    apply_lazy(node, start, end);
    if (start > r || end < l) return 0;
    if (l <= start && end <= r) return tree[node];
    int mid = (start + end) / 2;
    return range_sum(node * 2, start, mid, l, r) + 
           range_sum(node * 2 + 1, mid + 1, end, l, r);
}

