#define LLONG_MIN_VAL (-9223372036854775807LL - 1)

typedef long long ll;

ll tree[4*MAXN];
ll lazy[4*MAXN];
int n, q;

void build(int node, int start, int end) {
    tree[node] = 0;
    lazy[node] = LLONG_MIN_VAL;
    if (start == end) return;
    int mid = (start + end) / 2;
    build(2*node, start, mid);
    build(2*node+1, mid+1, end);
}

void pushDown(int node, int start, int end) {
    if (lazy[node] != LLONG_MIN_VAL) {
        int mid = (start + end) / 2;
        int leftLen = mid - start + 1;
        int rightLen = end - mid;

        tree[2*node] = lazy[node] * leftLen;
        lazy[2*node] = lazy[node];

        tree[2*node+1] = lazy[node] * rightLen;
        lazy[2*node+1] = lazy[node];

        lazy[node] = LLONG_MIN_VAL;
    }
}

void update(int node, int start, int end, int l, int r, ll val) {
    if (r < start || end < l) return;
    if (l <= start && end <= r) {
        tree[node] = val * (end - start + 1);
        lazy[node] = val;
        return;
    }
    pushDown(node, start, end);
    int mid = (start + end) / 2;
    update(2*node, start, mid, l, r, val);
    update(2*node+1, mid+1, end, l, r, val);
    tree[node] = tree[2*node] + tree[2*node+1];
}

ll query(int node, int start, int end, int l, int r) {
    if (r < start || end < l) return 0;
    if (l <= start && end <= r) return tree[node];
    pushDown(node, start, end);
    int mid = (start + end) / 2;
    ll leftSum = query(2*node, start, mid, l, r);
    ll rightSum = query(2*node+1, mid+1, end, l, r);
    return leftSum + rightSum;
}

