    seg[idx].sum = (ll)(r - l + 1) * val;
    seg[idx].lazy = val;
    seg[idx].has_lazy = 1;
}

void push(int idx, int l, int r) {
    if (!seg[idx].has_lazy || l == r) return;
    int mid = (l + r) / 2;
    apply(idx * 2, l, mid, seg[idx].lazy);
    apply(idx * 2 + 1, mid + 1, r, seg[idx].lazy);
    seg[idx].has_lazy = 0;
}

void update(int idx, int l, int r, int ql, int qr, ll val) {
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) {
        apply(idx, l, r, val);
        return;
    }
    push(idx, l, r);
    int mid = (l + r) / 2;
    update(idx * 2, l, mid, ql, qr, val);
    update(idx * 2 + 1, mid + 1, r, ql, qr, val);
    seg[idx].sum = seg[idx * 2].sum + seg[idx * 2 + 1].sum;
}

ll query(int idx, int l, int r, int ql, int qr) {
    if (qr < l || r < ql) return 0;
    if (ql <= l && r <= qr) return seg[idx].sum;
    push(idx, l, r);
    int mid = (l + r) / 2;
    return query(idx * 2, l, mid, ql, qr) +
           query(idx * 2 + 1, mid + 1, r, ql, qr);
}

