typedef long long ll;

class LazySegmentTree {
    int n;
    vector<ll> tree, lazy;

public:
    LazySegmentTree(int size) {
        n = 1;
        while (n < size) n <<= 1;
        tree.assign(2 * n, 0);
        lazy.assign(2 * n, LLONG_MAX); // LLONG_MAX means no pending update
    }

    void push(int idx, int l, int r) {
        if (lazy[idx] != LLONG_MAX) {
            tree[idx] = lazy[idx] * (r - l + 1);
            if (l != r) {
                lazy[idx * 2] = lazy[idx];
                lazy[idx * 2 + 1] = lazy[idx];
            }
            lazy[idx] = LLONG_MAX;
        }
    }

    void rangeUpdate(int l, int r, ll x, int idx, int left, int right) {
        push(idx, left, right);
        if (r < left || right < l) return;
        if (l <= left && right <= r) {
            lazy[idx] = x;
            push(idx, left, right);
            return;
        }
        int mid = (left + right) / 2;
        rangeUpdate(l, r, x, idx * 2, left, mid);
        rangeUpdate(l, r, x, idx * 2 + 1, mid + 1, right);
        tree[idx] = tree[idx * 2] + tree[idx * 2 + 1];
    }

    void rangeUpdate(int l, int r, ll x) {
        rangeUpdate(l, r, x, 1, 0, n - 1);
    }

    ll rangeSum(int l, int r, int idx, int left, int right) {
        push(idx, left, right);
        if (r < left || right < l) return 0;
        if (l <= left && right <= r) return tree[idx];
        int mid = (left + right) / 2;
        return rangeSum(l, r, idx * 2, left, mid) +
               rangeSum(l, r, idx * 2 + 1, mid + 1, right);
    }

    ll rangeSum(int l, int r) {
        return rangeSum(l, r, 1, 0, n - 1);
    }
};

