struct LazySegTree {
    int n;
    vector<long long> seg, lazy;
    vector<bool> hasLazy;

    LazySegTree(int sz) {
        n = 1;
        while (n < sz) n <<= 1;
        seg.assign(2 * n, 0);
        lazy.assign(2 * n, 0);
        hasLazy.assign(2 * n, false);
    }

    void apply(int k, int l, int r, long long x) {
        seg[k] = (r - l) * x;
        lazy[k] = x;
        hasLazy[k] = true;
    }

    void push(int k, int l, int r) {
        if (!hasLazy[k] || r - l == 1) return;
        int m = (l + r) >> 1;
        apply(k << 1, l, m, lazy[k]);
        apply(k << 1 | 1, m, r, lazy[k]);
        hasLazy[k] = false;
    }

    void update(int a, int b, long long x, int k, int l, int r) {
        if (r <= a || b <= l) return;
        if (a <= l && r <= b) {
            apply(k, l, r, x);
            return;
        }
        push(k, l, r);
        int m = (l + r) >> 1;
        update(a, b, x, k << 1, l, m);
        update(a, b, x, k << 1 | 1, m, r);
        seg[k] = seg[k << 1] + seg[k << 1 | 1];
    }

    long long query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return 0;
        if (a <= l && r <= b) return seg[k];
        push(k, l, r);
        int m = (l + r) >> 1;
        return query(a, b, k << 1, l, m) + query(a, b, k << 1 | 1, m, r);
    }

    void update(int l, int r, long long x) { update(l, r, x, 1, 0, n); }
    long long query(int l, int r) { return query(l, r, 1, 0, n); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    LazySegTree st(n);

    for (int i = 0; i < q; i++) {
        int com, s, t;
        cin >> com >> s >> t;
        if (com == 0) {
            long long x;
            cin >> x;
            st.update(s, t + 1, x);
        } else {
            cout << st.query(s, t + 1) << '\n';
        }
    }

    return 0;
}

