import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class SegmentTree {
        int n;
        long[] tree;
        long[] lazy;
        boolean[] hasLazy;

        SegmentTree(int size) {
            n = size;
            tree = new long[4 * n];
            lazy = new long[4 * n];
            hasLazy = new boolean[4 * n];
        }

        void push(int node, int l, int r) {
            if (!hasLazy[node]) return;
            tree[node] = (r - l + 1L) * lazy[node];
            if (l != r) {
                int left = node << 1;
                int right = left | 1;
                lazy[left] = lazy[node];
                lazy[right] = lazy[node];
                hasLazy[left] = true;
                hasLazy[right] = true;
            }
            hasLazy[node] = false;
        }

        void update(int node, int l, int r, int ql, int qr, long val) {
            push(node, l, r);
            if (r < ql || qr < l) return;
            if (ql <= l && r <= qr) {
                lazy[node] = val;
                hasLazy[node] = true;
                push(node, l, r);
                return;
            }
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ql, qr, val);
            update(node << 1 | 1, mid + 1, r, ql, qr, val);
            tree[node] = tree[node << 1] + tree[node << 1 | 1];
        }

        long query(int node, int l, int r, int ql, int qr) {
            push(node, l, r);
            if (r < ql || qr < l) return 0;
            if (ql <= l && r <= qr) return tree[node];
            int mid = (l + r) >>> 1;
            return query(node << 1, l, mid, ql, qr)
                 + query(node << 1 | 1, mid + 1, r, ql, qr);
        }

        void update(int l, int r, long val) {
            update(1, 0, n - 1, l, r, val);
        }

        long query(int l, int r) {
            return query(1, 0, n - 1, l, r);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int q = fs.nextInt();

        SegmentTree seg = new SegmentTree(n);
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < q; i++) {
            int type = fs.nextInt();
            int s = fs.nextInt();
            int t = fs.nextInt();
            if (type == 0) {
                long x = fs.nextLong();
                seg.update(s, t, x);
            } else {
                out.append(seg.query(s, t)).append('\n');
            }
        }

