        while size < n:
            size <<= 1
        self.size = size
        self.data = [0] * (2 * size)
        self.lazy = [None] * (2 * size)

    def _apply(self, idx, val, length):
        self.data[idx] = val * length
        self.lazy[idx] = val

    def _push(self, idx, left_len, right_len):
        if self.lazy[idx] is not None:
            self._apply(idx * 2, self.lazy[idx], left_len)
            self._apply(idx * 2 + 1, self.lazy[idx], right_len)
            self.lazy[idx] = None

    def update(self, l, r, val):
        self._update(l, r, val, 1, 0, self.size - 1)

    def _update(self, l, r, val, idx, left, right):
        if l <= left and right <= r:
            self._apply(idx, val, right - left + 1)
            return
        mid = (left + right) // 2
        self._push(idx, mid - left + 1, right - mid)
        if l <= mid:
            self._update(l, r, val, idx * 2, left, mid)
        if r > mid:
            self._update(l, r, val, idx * 2 + 1, mid + 1, right)
        self.data[idx] = self.data[idx * 2] + self.data[idx * 2 + 1]

    def query(self, l, r):
        return self._query(l, r, 1, 0, self.size - 1)

    def _query(self, l, r, idx, left, right):
        if l <= left and right <= r:
            return self.data[idx]
        mid = (left + right) // 2
        self._push(idx, mid - left + 1, right - mid)
        res = 0
        if l <= mid:
            res += self._query(l, r, idx * 2, left, mid)
        if r > mid:
            res += self._query(l, r, idx * 2 + 1, mid + 1, right)
        return res


