import sys

sys.setrecursionlimit(1 << 25)

class LazySegTree:
    def __init__(self, n):
        self.n = n
        self.size = 1
        while self.size < n:
            self.size <<= 1
        self.seg = [0] * (2 * self.size)
        self.lazy = [None] * (2 * self.size)

    def _apply(self, k, l, r, x):
        self.seg[k] = (r - l) * x
        self.lazy[k] = x

    def _push(self, k, l, r):
        if self.lazy[k] is None or r - l == 1:
            return
        m = (l + r) >> 1
        x = self.lazy[k]
        self._apply(k * 2, l, m, x)
        self._apply(k * 2 + 1, m, r, x)
        self.lazy[k] = None

    def update(self, a, b, x, k=1, l=0, r=None):
        if r is None:
            r = self.size
        if b <= l or r <= a:
            return
        if a <= l and r <= b:
            self._apply(k, l, r, x)
            return
        self._push(k, l, r)
        m = (l + r) >> 1
        self.update(a, b, x, k * 2, l, m)
        self.update(a, b, x, k * 2 + 1, m, r)
        self.seg[k] = self.seg[k * 2] + self.seg[k * 2 + 1]

    def query(self, a, b, k=1, l=0, r=None):
        if r is None:
            r = self.size
        if b <= l or r <= a:
            return 0
        if a <= l and r <= b:
            return self.seg[k]
        self._push(k, l, r)
        m = (l + r) >> 1
        return self.query(a, b, k * 2, l, m) + self.query(a, b, k * 2 + 1, m, r)


def main():
    input = sys.stdin.readline
    n, q = map(int, input().split())
    st = LazySegTree(n)
    out = []

    for _ in range(q):
        tmp = list(map(int, input().split()))
        if tmp[0] == 0:
            _, s, t, x = tmp
            st.update(s, t + 1, x)
        else:
            _, s, t = tmp
            out.append(str(st.query(s, t + 1)))

    print("\n".join(out))

if __name__ == "__main__":
